import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";

type UnknownRecord = Record<string, unknown>;

type PipelineStatus = {
  running?: boolean;
  current_step?: string;
  step?: string;
  obs?: UnknownRecord;
  obs_status?: unknown;
  obs_connected?: boolean;
  obs_virtual_camera?: boolean;
  obs_streaming?: boolean;
  obs_fps?: number;
  obs_scene?: string;
  obs_error?: string;
  last_result?: {
    returncode?: number | null;
    stdout?: string;
    stderr?: string;
  } | null;
} & UnknownRecord;

type HealthResponse = {
  ok?: boolean;
  status?: string;
  version?: string;
  environment?: string;
  uptime_seconds?: number;
  uptime?: number | string;
  timestamp?: string;
  services?: Record<string, unknown>;
  checks?: Record<string, unknown>;
  dependencies?: Record<string, unknown>;
  error?: string;
} & UnknownRecord;

type ObsViewModel = {
  connected: boolean | null;
  virtualCamera: boolean | null;
  streaming: boolean | null;
  fps: number | null;
  scene: string;
  statusText: string;
  errorText: string;
};

type HealthViewModel = {
  healthy: boolean | null;
  statusText: string;
  version: string;
  environment: string;
  uptimeText: string;
  timestamp: string;
  checks: Array<{
    name: string;
    status: string;
    healthy: boolean | null;
  }>;
};

const API = {
  pipelineStatus: "/api/pipeline/status",
  health: "/api/health",
};

function isRecord(value: unknown): value is UnknownRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function readString(value: unknown): string | undefined {
  if (typeof value === "string" && value.trim()) return value.trim();
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  if (typeof value === "boolean") return value ? "true" : "false";
  return undefined;
}

function readBoolean(value: unknown): boolean | null {
  if (typeof value === "boolean") return value;

  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();

    if (["true", "ok", "healthy", "connected", "online", "running", "active", "yes"].includes(normalized)) {
      return true;
    }

    if (["false", "fail", "failed", "unhealthy", "disconnected", "offline", "stopped", "inactive", "no"].includes(normalized)) {
      return false;
    }
  }

  if (typeof value === "number" && Number.isFinite(value)) {
    return value > 0;
  }

  return null;
}

function readNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;

  if (typeof value === "string") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }

  return null;
}

function pickFirstString(...values: unknown[]): string {
  for (const value of values) {
    const str = readString(value);
    if (str) return str;
  }

  return "--";
}

function pickFirstBoolean(...values: unknown[]): boolean | null {
  for (const value of values) {
    const bool = readBoolean(value);
    if (bool !== null) return bool;
  }

  return null;
}

function pickFirstNumber(...values: unknown[]): number | null {
  for (const value of values) {
    const num = readNumber(value);
    if (num !== null) return num;
  }

  return null;
}

function formatDuration(secondsLike: unknown): string {
  const seconds = readNumber(secondsLike);

  if (seconds === null) {
    const text = readString(secondsLike);
    return text || "--";
  }

  const safeSeconds = Math.max(0, Math.floor(seconds));
  const h = Math.floor(safeSeconds / 3600);
  const m = Math.floor((safeSeconds % 3600) / 60);
  const s = safeSeconds % 60;

  if (h > 0) {
    return `${h}小时 ${m}分 ${s}秒`;
  }

  if (m > 0) {
    return `${m}分 ${s}秒`;
  }

  return `${s}秒`;
}

function formatDateTime(value: unknown): string {
  const raw = readString(value);
  if (!raw) return "--";

  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw;

  return date.toLocaleString();
}

function normalizeStatusText(value: unknown): string {
  const text = readString(value);
  if (!text) return "--";

  const lower = text.toLowerCase();

  if (["ok", "healthy", "success", "pass", "ready"].includes(lower)) return "正常";
  if (["running", "active", "online"].includes(lower)) return "运行中";
  if (["warning", "warn"].includes(lower)) return "警告";
  if (["error", "failed", "fail", "unhealthy"].includes(lower)) return "异常";
  if (["offline", "disconnected", "stopped"].includes(lower)) return "离线";

  return text;
}

function getObjectValue(source: UnknownRecord | undefined, keys: string[]): unknown {
  if (!source) return undefined;

  for (const key of keys) {
    if (key in source) return source[key];
  }

  return undefined;
}

function buildObsViewModel(status: PipelineStatus | null): ObsViewModel {
  if (!status) {
    return {
      connected: null,
      virtualCamera: null,
      streaming: null,
      fps: null,
      scene: "--",
      statusText: "未连接",
      errorText: "",
    };
  }

  const obs = isRecord(status.obs) ? status.obs : undefined;
  const obsStatus = isRecord(status.obs_status) ? status.obs_status : undefined;

  const connected = pickFirstBoolean(
    status.obs_connected,
    getObjectValue(obs, ["connected", "is_connected", "online"]),
    getObjectValue(obsStatus, ["connected", "is_connected", "online", "status"])
  );

  const virtualCamera = pickFirstBoolean(
    status.obs_virtual_camera,
    getObjectValue(obs, ["virtual_camera", "virtualCamera", "virtual_camera_active", "virtualCameraActive"]),
    getObjectValue(obsStatus, ["virtual_camera", "virtualCamera", "virtual_camera_active", "virtualCameraActive"])
  );

  const streaming = pickFirstBoolean(
    status.obs_streaming,
    getObjectValue(obs, ["streaming", "is_streaming", "output_active", "recording", "live"]),
    getObjectValue(obsStatus, ["streaming", "is_streaming", "output_active", "recording", "live"])
  );

  const fps = pickFirstNumber(
    status.obs_fps,
    getObjectValue(obs, ["fps", "obs_fps", "render_fps", "output_fps"]),
    getObjectValue(obsStatus, ["fps", "obs_fps", "render_fps", "output_fps"])
  );

  const scene = pickFirstString(
    status.obs_scene,
    getObjectValue(obs, ["scene", "current_scene", "currentScene", "active_scene"]),
    getObjectValue(obsStatus, ["scene", "current_scene", "currentScene", "active_scene"])
  );

  const explicitStatus = pickFirstString(
    getObjectValue(obs, ["status", "state"]),
    getObjectValue(obsStatus, ["status", "state"]),
    status.obs_status
  );

  const errorText = pickFirstString(
    status.obs_error,
    getObjectValue(obs, ["error", "message"]),
    getObjectValue(obsStatus, ["error", "message"])
  );

  let statusText = normalizeStatusText(explicitStatus);

  if (statusText === "--") {
    if (connected === true && virtualCamera === true) statusText = "OBS 已连接，虚拟摄像头已开启";
    else if (connected === true) statusText = "OBS 已连接";
    else if (connected === false) statusText = "OBS 未连接";
    else statusText = "OBS 状态未返回";
  }

  return {
    connected,
    virtualCamera,
    streaming,
    fps,
    scene,
    statusText,
    errorText: errorText === "--" ? "" : errorText,
  };
}

function buildHealthViewModel(health: HealthResponse | null): HealthViewModel {
  if (!health) {
    return {
      healthy: null,
      statusText: "未连接",
      version: "--",
      environment: "--",
      uptimeText: "--",
      timestamp: "--",
      checks: [],
    };
  }

  const healthy = pickFirstBoolean(health.ok, health.status);
  const services = isRecord(health.services) ? health.services : {};
  const checks = isRecord(health.checks) ? health.checks : {};
  const dependencies = isRecord(health.dependencies) ? health.dependencies : {};

  const mergedChecks = {
    ...services,
    ...checks,
    ...dependencies,
  };

  return {
    healthy,
    statusText: normalizeStatusText(health.status ?? health.ok),
    version: pickFirstString(health.version),
    environment: pickFirstString(health.environment, health.env, health.mode),
    uptimeText: formatDuration(health.uptime_seconds ?? health.uptime),
    timestamp: formatDateTime(health.timestamp ?? health.time ?? health.updated_at),
    checks: Object.entries(mergedChecks).map(([name, value]) => {
      if (isRecord(value)) {
        const rawStatus = value.status ?? value.ok ?? value.healthy ?? value.state;
        return {
          name,
          status: normalizeStatusText(rawStatus),
          healthy: readBoolean(rawStatus),
        };
      }

      return {
        name,
        status: normalizeStatusText(value),
        healthy: readBoolean(value),
      };
    }),
  };
}

function StatusPill(props: {
  children: React.ReactNode;
  tone?: "ok" | "warn" | "idle" | "running";
}) {
  const toneClass = {
    ok: "border-emerald-400/30 bg-emerald-400/10 text-emerald-100",
    warn: "border-red-400/35 bg-red-400/10 text-red-100",
    idle: "border-white/12 bg-white/5 text-[oklch(80%_0_0)]",
    running:
      "border-[oklch(84%_0.19_80/0.46)] bg-[oklch(84%_0.19_80/0.12)] text-[oklch(91%_0.06_84)]",
  }[props.tone || "idle"];

  return (
    <span className={`inline-flex items-center rounded-full border px-3 py-1 text-xs font-medium ${toneClass}`}>
      {props.children}
    </span>
  );
}

function SwitchView(props: {
  checked: boolean | null;
  label: string;
  description: string;
}) {
  const checked = props.checked === true;
  const unknown = props.checked === null;

  return (
    <div className="flex items-center justify-between gap-5 rounded-3xl border border-[oklch(22%_0.018_95)] bg-[oklch(10%_0.006_95)] p-5">
      <div>
        <div className="text-sm font-semibold text-[oklch(91%_0_0)]">{props.label}</div>
        <div className="mt-1 text-xs leading-5 text-[oklch(68%_0_0)]">{props.description}</div>
      </div>

      <div
        className={[
          "relative h-8 w-14 shrink-0 rounded-full border transition",
          checked
            ? "border-[oklch(84%_0.19_80/0.55)] bg-[oklch(84%_0.19_80/0.28)]"
            : "border-white/15 bg-white/8",
          unknown ? "opacity-45" : "",
        ].join(" ")}
        aria-label={props.label}
      >
        <div
          className={[
            "absolute top-1 h-6 w-6 rounded-full transition",
            checked
              ? "left-7 bg-[oklch(84%_0.19_80)] shadow-[0_0_22px_oklch(84%_0.19_80/0.42)]"
              : "left-1 bg-[oklch(72%_0_0)]",
          ].join(" ")}
        />
      </div>
    </div>
  );
}

function InfoCard(props: {
  label: string;
  value: React.ReactNode;
  hint?: string;
  emphasis?: boolean;
}) {
  return (
    <div
      className={[
        "rounded-3xl border p-5 shadow-[0_18px_60px_rgba(0,0,0,0.24)]",
        "border-[oklch(22%_0.018_95)] bg-[linear-gradient(145deg,oklch(12%_0.008_95),oklch(8%_0.006_95))]",
        props.emphasis ? "ring-1 ring-[oklch(84%_0.19_80/0.38)]" : "",
      ].join(" ")}
    >
      <div className="text-sm text-[oklch(72%_0_0)]">{props.label}</div>
      <div className="mt-3 text-2xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
        {props.value}
      </div>
      {props.hint ? (
        <div className="mt-2 text-xs leading-5 text-[oklch(68%_0_0)]">{props.hint}</div>
      ) : null}
    </div>
  );
}

function CheckRow(props: {
  name: string;
  status: string;
  healthy: boolean | null;
}) {
  const tone = props.healthy === true ? "ok" : props.healthy === false ? "warn" : "idle";

  return (
    <div className="flex items-center justify-between gap-4 rounded-2xl border border-white/10 bg-black/20 px-4 py-3">
      <span className="truncate text-sm text-[oklch(84%_0_0)]">{props.name}</span>
      <StatusPill tone={tone}>{props.status}</StatusPill>
    </div>
  );
}

function LoadingBlock() {
  return (
    <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-4">
      {Array.from({ length: 4 }).map((_, index) => (
        <div
          key={index}
          className="rounded-3xl border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5"
        >
          <div className="h-4 w-24 animate-pulse rounded-full bg-white/10" />
          <div className="mt-4 h-8 w-32 animate-pulse rounded-full bg-white/10" />
          <div className="mt-3 h-3 w-40 animate-pulse rounded-full bg-white/10" />
        </div>
      ))}
    </div>
  );
}

export default function SettingsPage() {
  const [pipelineStatus, setPipelineStatus] = useState<PipelineStatus | null>(null);
  const [health, setHealth] = useState<HealthResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastLoadedAt, setLastLoadedAt] = useState<Date | null>(null);

  const abortRef = useRef<AbortController | null>(null);

  const obsView = useMemo(() => buildObsViewModel(pipelineStatus), [pipelineStatus]);
  const healthView = useMemo(() => buildHealthViewModel(health), [health]);

  const loadSettings = useCallback(async (silent = false) => {
    abortRef.current?.abort();

    const controller = new AbortController();
    abortRef.current = controller;

    try {
      if (silent) {
        setRefreshing(true);
      } else {
        setLoading(true);
      }

      setError(null);

      const [pipelineResponse, healthResponse] = await Promise.all([
        fetch(API.pipelineStatus, {
          method: "GET",
          headers: {
            Accept: "application/json",
          },
          signal: controller.signal,
        }),
        fetch(API.health, {
          method: "GET",
          headers: {
            Accept: "application/json",
          },
          signal: controller.signal,
        }),
      ]);

      if (!pipelineResponse.ok) {
        throw new Error(`管线状态接口异常：HTTP ${pipelineResponse.status}`);
      }

      if (!healthResponse.ok) {
        throw new Error(`健康检查接口异常：HTTP ${healthResponse.status}`);
      }

      const pipelinePayload = (await pipelineResponse.json()) as PipelineStatus;
      const healthPayload = (await healthResponse.json()) as HealthResponse;

      setPipelineStatus(pipelinePayload);
      setHealth(healthPayload);
      setLastLoadedAt(new Date());
    } catch (err) {
      if (err instanceof DOMException && err.name === "AbortError") return;

      setError(err instanceof Error ? err.message : "读取设置状态失败");
      setPipelineStatus(null);
      setHealth(null);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    loadSettings(false);

    const timer = window.setInterval(() => {
      loadSettings(true);
    }, 5000);

    return () => {
      window.clearInterval(timer);
      abortRef.current?.abort();
    };
  }, [loadSettings]);

  const obsTone =
    obsView.connected === true ? "ok" : obsView.connected === false ? "warn" : "idle";

  const healthTone =
    healthView.healthy === true ? "ok" : healthView.healthy === false ? "warn" : "idle";

  return (
    <main className="min-h-screen bg-[oklch(7%_0.006_95)] text-[oklch(88%_0_0)]">
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute -left-44 top-[-8rem] h-[30rem] w-[30rem] rounded-full bg-[oklch(84%_0.19_80/0.12)] blur-3xl" />
        <div className="absolute bottom-[-10rem] right-[-8rem] h-[34rem] w-[34rem] rounded-full bg-[oklch(77%_0.13_82/0.10)] blur-3xl" />
        <div className="absolute inset-x-0 top-0 h-px bg-[linear-gradient(90deg,transparent,oklch(84%_0.19_80/0.48),transparent)]" />
      </div>

      <section className="relative mx-auto max-w-7xl px-6 py-8 lg:px-8">
        <header className="mb-8 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
          <div>
            <div className="mb-3 flex flex-wrap items-center gap-3">
              <StatusPill tone={obsTone}>OBS：{obsView.statusText}</StatusPill>
              <StatusPill tone={healthTone}>服务：{healthView.statusText}</StatusPill>
              {refreshing ? <StatusPill tone="running">同步中</StatusPill> : null}
            </div>

            <h1 className="text-4xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
              PHS 系统设置
            </h1>

            <p className="mt-3 max-w-2xl text-sm leading-6 text-[oklch(72%_0_0)]">
              通过真实接口读取 OBS、管线与后端健康状态，接口来源：
              <span className="font-medium text-[oklch(91%_0.06_84)]"> GET /api/pipeline/status</span>
              <span className="text-[oklch(60%_0_0)]"> / </span>
              <span className="font-medium text-[oklch(91%_0.06_84)]">GET /api/health</span>
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            {lastLoadedAt ? (
              <div className="rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-xs text-[oklch(72%_0_0)]">
                最近同步：{lastLoadedAt.toLocaleTimeString()}
              </div>
            ) : null}

            <button
              type="button"
              onClick={() => loadSettings(true)}
              disabled={loading || refreshing}
              className="rounded-2xl bg-[oklch(84%_0.19_80)] px-5 py-3 text-sm font-semibold text-[oklch(8%_0.006_95)] shadow-[0_16px_42px_oklch(84%_0.19_80/0.22)] transition hover:bg-[oklch(86%_0.07_84)] active:bg-[oklch(77%_0.13_82)] disabled:cursor-not-allowed disabled:opacity-50"
            >
              {refreshing ? "刷新中..." : "刷新状态"}
            </button>
          </div>
        </header>

        {error ? (
          <div className="mb-6 rounded-3xl border border-red-400/30 bg-red-400/10 px-5 py-4 text-sm text-red-100">
            {error}
          </div>
        ) : null}

        {loading ? (
          <LoadingBlock />
        ) : (
          <>
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-4">
              <InfoCard
                label="OBS 连接状态"
                value={obsView.connected === true ? "已连接" : obsView.connected === false ? "未连接" : "--"}
                hint="来自 /api/pipeline/status"
                emphasis
              />
              <InfoCard
                label="虚拟摄像头"
                value={
                  obsView.virtualCamera === true
                    ? "已开启"
                    : obsView.virtualCamera === false
                      ? "未开启"
                      : "--"
                }
                hint="用于直播画面输出"
              />
              <InfoCard
                label="OBS 帧率"
                value={obsView.fps === null ? "--" : `${obsView.fps} FPS`}
                hint="后端未返回则显示 --"
              />
              <InfoCard
                label="后端健康"
                value={healthView.statusText}
                hint="来自 /api/health"
                emphasis
              />
            </div>

            <div className="mt-6 grid grid-cols-1 gap-6 xl:grid-cols-[0.95fr_1.05fr]">
              <section className="rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5 shadow-[0_24px_90px_rgba(0,0,0,0.28)]">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <h2 className="text-xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
                      OBS 输出设置
