                  <StatusPill tone={obsTone}>{obsView.statusText}</StatusPill>
                </div>

                <div className="mt-5 space-y-4">
                  <SwitchView
                    checked={obsView.connected}
                    label="OBS WebSocket 连接"
                    description="后端管线返回 connected / obs_connected 等字段时自动点亮。"
                  />

                  <SwitchView
                    checked={obsView.virtualCamera}
                    label="OBS 虚拟摄像头"
                    description="用于抖音、快手等直播平台识别 PHS 画面源。"
                  />

                  <SwitchView
                    checked={obsView.streaming}
                    label="推流 / 录制输出"
                    description="读取 streaming / output_active / live 等真实状态字段。"
                  />
                </div>

                <div className="mt-5 grid grid-cols-1 gap-3 md:grid-cols-2">
                  <div className="rounded-3xl border border-white/10 bg-black/20 p-4">
                    <div className="text-xs text-[oklch(64%_0_0)]">当前场景</div>
                    <div className="mt-2 truncate text-sm font-semibold text-[oklch(91%_0_0)]">
                      {obsView.scene}
                    </div>
                  </div>

                  <div className="rounded-3xl border border-white/10 bg-black/20 p-4">
                    <div className="text-xs text-[oklch(64%_0_0)]">管线步骤</div>
                    <div className="mt-2 truncate text-sm font-semibold text-[oklch(91%_0_0)]">
                      {pipelineStatus?.current_step || pipelineStatus?.step || "--"}
