              </section>

              <section className="rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5 shadow-[0_24px_90px_rgba(0,0,0,0.28)]">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <h2 className="text-xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
