                    <p className="mt-1 text-sm leading-6 text-[oklch(72%_0_0)]">
                      读取后端健康状态、版本、运行时间与依赖检查。
                    </p>
                  </div>

                  <StatusPill tone={healthTone}>{healthView.statusText}</StatusPill>
                </div>

                <div className="mt-5 grid grid-cols-1 gap-3 md:grid-cols-2">
                  <div className="rounded-3xl border border-white/10 bg-black/20 p-4">
                    <div className="text-xs text-[oklch(64%_0_0)]">版本</div>
                    <div className="mt-2 truncate text-sm font-semibold text-[oklch(91%_0_0)]">
                      {healthView.version}
