                  <div className="rounded-3xl border border-white/10 bg-black/20 p-4">
                    <div className="text-xs text-[oklch(64%_0_0)]">运行时间</div>
                    <div className="mt-2 truncate text-sm font-semibold text-[oklch(91%_0_0)]">
                      {healthView.uptimeText}
                    </div>
                  </div>

                  <div className="rounded-3xl border border-white/10 bg-black/20 p-4">
                    <div className="text-xs text-[oklch(64%_0_0)]">接口时间</div>
                    <div className="mt-2 truncate text-sm font-semibold text-[oklch(91%_0_0)]">
                      {healthView.timestamp}
                    </div>
                  </div>
                </div>

                <div className="mt-5">
                  <div className="mb-3 text-sm font-semibold text-[oklch(91%_0_0)]">
                    服务依赖
                  </div>

                  {healthView.checks.length > 0 ? (
                    <div className="space-y-3">
                      {healthView.checks.map((check) => (
                        <CheckRow
                          key={check.name}
                          name={check.name}
                          status={check.status}
                          healthy={check.healthy}
                        />
                      ))}
                    </div>
                  ) : (
                    <div className="rounded-3xl border border-dashed border-[oklch(32%_0.018_95)] bg-black/20 p-6 text-center text-sm leading-6 text-[oklch(72%_0_0)]">
                      /api/health 未返回 services、checks 或 dependencies 字段。
                    </div>
                  )}
                </div>
              </section>
            </div>

            <section className="mt-6 rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5 shadow-[0_24px_90px_rgba(0,0,0,0.28)]">
              <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <h2 className="text-xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
                    原始接口摘要
                  </h2>
                  <p className="mt-1 text-sm leading-6 text-[oklch(72%_0_0)]">
                    用于开发联调，确保 SettingsPage 不再依赖硬编码模拟数据。
                  </p>
                </div>

                <StatusPill tone="idle">5 秒自动刷新</StatusPill>
              </div>

              <div className="mt-5 grid grid-cols-1 gap-4 lg:grid-cols-2">
                <div className="rounded-3xl border border-white/10 bg-black/25 p-4">
                  <div className="mb-3 text-xs font-semibold uppercase tracking-[0.18em] text-[oklch(84%_0.19_80)]">
                    /api/pipeline/status
                  </div>

                  <pre className="max-h-72 overflow-auto whitespace-pre-wrap break-words text-xs leading-6 text-[oklch(82%_0_0)]">
                    {pipelineStatus ? JSON.stringify(pipelineStatus, null, 2) : "暂无数据"}
                  </pre>
                </div>

                <div className="rounded-3xl border border-white/10 bg-black/25 p-4">
                  <div className="mb-3 text-xs font-semibold uppercase tracking-[0.18em] text-[oklch(84%_0.19_80)]">
                    /api/health
                  </div>

                  <pre className="max-h-72 overflow-auto whitespace-pre-wrap break-words text-xs leading-6 text-[oklch(82%_0_0)]">
                    {health ? JSON.stringify(health, null, 2) : "暂无数据"}
                  </pre>
                </div>
              </div>
            </section>
          </>
        )}
      </section>
    </main>
  );
}
